import pandas as pd


def add_value_tier(df):
    """Add a 'value_tier' column: 'high' if amount > 1000, 'mid' if 200-1000, 'low' otherwise."""
    result = []
    for idx, row in df.iterrows():
        if row['amount'] > 1000:
            result.append('high')
        elif row['amount'] >= 200:
            result.append('mid')
        else:
            result.append('low')
    df['value_tier'] = result
    return df
